



SET FOREIGN_KEY_CHECKS=1;

-- Performance indexes
CREATE INDEX idx_tx_account_time ON transactions(account_id, transaction_time);
CREATE INDEX idx_tx_time_status ON transactions(transaction_time, status);
CREATE INDEX idx_tx_amount ON transactions(amount);
CREATE INDEX idx_tx_city_time ON transactions(city, transaction_time);
CREATE INDEX idx_card_account_time ON card_transactions(account_id, transaction_time);
CREATE INDEX idx_card_merchant ON card_transactions(merchant_id);
CREATE INDEX idx_fraud_risk ON fraud_alerts(risk_score, alert_status);
CREATE INDEX idx_loans_customer_status ON loans(customer_id, loan_status);
CREATE INDEX idx_payments_loan_date ON loan_payments(loan_id, payment_date);
CREATE INDEX idx_complaints_customer_date ON customer_complaints(customer_id, complaint_date);

-- Analytical views
CREATE OR REPLACE VIEW v_customer_transaction_summary AS
SELECT c.customer_id,
       CONCAT(c.first_name,' ',c.last_name) AS customer_name,
       c.risk_category,
       COUNT(t.transaction_id) AS transaction_count,
       COALESCE(SUM(CASE WHEN t.status='Success' THEN t.amount ELSE 0 END),0) AS successful_value,
       COALESCE(AVG(CASE WHEN t.status='Success' THEN t.amount END),0) AS avg_transaction
FROM customers c
JOIN accounts a ON a.customer_id=c.customer_id
LEFT JOIN transactions t ON t.account_id=a.account_id
GROUP BY c.customer_id,c.first_name,c.last_name,c.risk_category;

CREATE OR REPLACE VIEW v_branch_performance AS
SELECT b.branch_id,b.branch_name,b.city,
       COUNT(DISTINCT a.account_id) AS accounts,
       COUNT(t.transaction_id) AS transactions,
       COALESCE(SUM(CASE WHEN t.status='Success' THEN t.amount END),0) AS transaction_value
FROM branches b
LEFT JOIN accounts a ON a.branch_id=b.branch_id
LEFT JOIN transactions t ON t.account_id=a.account_id
GROUP BY b.branch_id,b.branch_name,b.city;

CREATE OR REPLACE VIEW v_loan_health AS
SELECT l.loan_id,l.customer_id,l.loan_type,l.principal_amount,
       COUNT(lp.payment_id) AS installments,
       SUM(CASE WHEN lp.payment_status='Missed' THEN 1 ELSE 0 END) AS missed_payments,
       ROUND(AVG(lp.days_late),2) AS avg_days_late,
       ROUND(SUM(lp.paid_amount),2) AS total_paid
FROM loans l
LEFT JOIN loan_payments lp ON lp.loan_id=l.loan_id
GROUP BY l.loan_id,l.customer_id,l.loan_type,l.principal_amount;

-- Stored procedure: customer risk snapshot
DELIMITER //
CREATE PROCEDURE sp_customer_risk(IN p_customer_id INT)
BEGIN
    SELECT c.customer_id,
           CONCAT(c.first_name,' ',c.last_name) AS customer_name,
           c.annual_income,
           c.risk_category,
           COUNT(t.transaction_id) AS transaction_count,
           ROUND(SUM(CASE WHEN t.status='Success' THEN t.amount ELSE 0 END),2) AS transaction_value,
           ROUND(AVG(CASE WHEN t.status='Success' THEN t.amount END),2) AS avg_transaction,
           COUNT(f.alert_id) AS fraud_alerts
    FROM customers c
    LEFT JOIN accounts a ON a.customer_id=c.customer_id
    LEFT JOIN transactions t ON t.account_id=a.account_id
    LEFT JOIN fraud_alerts f ON f.transaction_id=t.transaction_id
    WHERE c.customer_id=p_customer_id
    GROUP BY c.customer_id,c.first_name,c.last_name,c.annual_income,c.risk_category;
END//
DELIMITER ;

-- Trigger: block negative loan payments
DELIMITER //
CREATE TRIGGER trg_validate_loan_payment
BEFORE INSERT ON loan_payments
FOR EACH ROW
BEGIN
    IF NEW.paid_amount < 0 OR NEW.due_amount < 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT='Payment amounts cannot be negative';
    END IF;
END//
DELIMITER ;

-- Trigger: protect invalid fraud scores
DELIMITER //
CREATE TRIGGER trg_validate_fraud_score
BEFORE INSERT ON fraud_alerts
FOR EACH ROW
BEGIN
    IF NEW.risk_score < 0 OR NEW.risk_score > 100 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT='Fraud risk score must be between 0 and 100';
    END IF;
END//
DELIMITER ;



